static void clk_test_uncached_set_range ( struct kunit * test ) { struct clk_dummy_context * ctx = test -> priv ; struct clk_hw * hw = & ctx -> hw ; struct clk * clk = clk_hw_get_clk ( hw , NULL ) ; unsigned long rate ; KUNIT_ASSERT_EQ ( test , clk_set_rate_range ( clk , DUMMY_CLOCK_RATE_1 , DUMMY_CLOCK_RATE_2 ) , 0 ) ; rate = clk_get_rate ( clk ) ; KUNIT_ASSERT_GT ( test , rate , 0 ) ; KUNIT_EXPECT_GE ( test , rate , DUMMY_CLOCK_RATE_1 ) ; KUNIT_EXPECT_LE ( test , rate , DUMMY_CLOCK_RATE_2 ) ; } 